package bus

import (
	"bufio"
	"encoding/hex"
	"fmt"
	"os"
	"strconv"
	"strings"
	"testing"
)

// The committed vectors are generated by scripts/gen_bus_wire_vectors.py from
// the spec, independently of both codecs. This test holds the Go codec to them
// byte-for-byte, which is what makes "the Go client and the C client agree"
// evidence about the wire.
const vectorPath = "../../src/tests/fixtures/bus/wire_vectors.tsv"

// parseFields turns a "k=v;k=v" field column into a Frame, strictly: an unknown
// or repeated key, or a value that does not parse, is a hard failure — a lenient
// parser would let a corrupted vector assert something never checked.
func parseFields(t *testing.T, name, spec string) Frame {
	t.Helper()
	var f Frame
	seen := map[string]bool{}
	for _, tok := range strings.Split(spec, ";") {
		kv := strings.SplitN(tok, "=", 2)
		if len(kv) != 2 {
			t.Fatalf("vector %q: malformed field %q", name, tok)
		}
		k, v := kv[0], kv[1]
		if seen[k] {
			t.Fatalf("vector %q: field %q twice", name, k)
		}
		seen[k] = true
		u, err := strconv.ParseUint(v, 0, 64)
		if err != nil {
			t.Fatalf("vector %q: field %q value %q: %v", name, k, v, err)
		}
		switch k {
		case "flags":
			f.HdrFlags = uint16(u)
		case "ver":
			f.WireVersion = uint16(u)
		case "kind":
			f.EventKind = uint32(u)
		case "principal":
			f.PrincipalRef = uint32(u)
		case "corr":
			f.CorrelationID = u
		case "seq":
			f.Seq = u
		case "lts":
			f.LogicalTS = u
		case "pref":
			f.PayloadRef = u
		case "plen":
			f.PayloadLen = uint32(u)
		case "src":
			f.SrcHandle = uint32(u)
		case "dst":
			f.DstHandle = uint32(u)
		case "gen":
			f.Generation = uint32(u)
		default:
			t.Fatalf("vector %q: unknown field %q", name, k)
		}
	}
	if len(seen) != 12 {
		t.Fatalf("vector %q: expected 12 fields, got %d", name, len(seen))
	}
	return f
}

func fieldsString(f *Frame) string {
	return fmt.Sprintf(
		"flags=0x%04x;ver=%d;kind=%d;principal=%d;corr=0x%016x;seq=%d;"+
			"lts=0x%016x;pref=0x%016x;plen=%d;src=%d;dst=%d;gen=%d",
		f.HdrFlags, f.WireVersion, f.EventKind, f.PrincipalRef, f.CorrelationID,
		f.Seq, f.LogicalTS, f.PayloadRef, f.PayloadLen, f.SrcHandle, f.DstHandle, f.Generation)
}

func TestWireVectors(t *testing.T) {
	fp, err := os.Open(vectorPath)
	if err != nil {
		t.Fatalf("open vectors: %v", err)
	}
	defer fp.Close()

	positives, negatives := 0, 0
	sc := bufio.NewScanner(fp)
	for sc.Scan() {
		line := sc.Text()
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		cols := strings.Split(line, "\t")
		if len(cols) != 4 {
			t.Fatalf("malformed vector line: %q", line)
		}
		name, expect, hx, fields := cols[0], cols[1], cols[2], cols[3]

		raw, err := hex.DecodeString(hx)
		if err != nil || len(raw) != HdrLen {
			t.Fatalf("vector %q: bad hex (%d bytes)", name, len(raw))
		}

		var got Frame
		res := Decode(raw, &got)
		if res.String() != expect {
			t.Fatalf("vector %q: decode gave %s, table says %s", name, res, expect)
		}

		if expect != "OK" {
			negatives++
			continue // a negative row has no valid frame to describe
		}
		positives++

		// Decode direction: committed bytes -> committed fields.
		want := parseFields(t, name, fields)
		if got != want {
			t.Fatalf("vector %q: decoded fields differ from the table", name)
		}

		// Encode direction: committed fields -> committed bytes.
		var enc [HdrLen]byte
		if want.Encode(enc[:]) != HdrLen {
			t.Fatalf("vector %q: encode refused a committed frame", name)
		}
		if encHex := hex.EncodeToString(enc[:]); encHex != hx {
			t.Fatalf("vector %q drifted:\n committed %s\n encoded   %s", name, hx, encHex)
		}
		if fs := fieldsString(&want); fs != fields {
			t.Fatalf("vector %q: field round-trip drifted:\n committed %s\n produced  %s",
				name, fields, fs)
		}
	}
	if err := sc.Err(); err != nil {
		t.Fatalf("scan: %v", err)
	}
	if positives == 0 || negatives == 0 {
		t.Fatalf("vector table needs both positive and negative rows (got %d/%d)",
			positives, negatives)
	}
	t.Logf("wire vectors: %d positive, %d negative, byte-exact against the C table",
		positives, negatives)
}

// TestValidationAxes independently judges every pattern x placement x length x
// correlation combination, mirroring the C combination matrix, so the Go
// validator is held to the contract rather than to whatever it happens to do.
func TestValidationAxes(t *testing.T) {
	patterns := []uint16{0, FNotification, FRequest, FReply, FCancel, FRequest | FReply}
	placements := []uint16{0, FInline, FArena, FInline | FArena}
	lens := []uint32{0, 64, MaxPayload, MaxPayload + 1}
	refs := []uint64{0, 0x40000}
	corrs := []uint64{0, 0xdeadbeefcafef00d}

	accepted, refused := 0, 0
	for _, p := range patterns {
		for _, q := range placements {
			for _, l := range lens {
				for _, rr := range refs {
					for _, cc := range corrs {
						f := Frame{HdrFlags: p | q, WireVersion: WireVersion,
							EventKind: KindModuleBase, PayloadLen: l, PayloadRef: rr,
							CorrelationID: cc}

						onePattern := p == FNotification || p == FRequest || p == FReply || p == FCancel
						onePlacement := q == FInline || q == FArena
						var placementOK, lengthOK, refOK bool
						if l > 0 {
							placementOK, lengthOK, refOK = onePlacement, l <= MaxPayload, true
						} else {
							placementOK, lengthOK, refOK = q == 0, true, rr == 0
						}
						var corrOK bool
						switch {
						case p == FNotification:
							corrOK = cc == 0
						case onePattern:
							corrOK = cc != 0
						default:
							corrOK = true
						}
						wantOK := onePattern && placementOK && lengthOK && refOK && corrOK

						res := f.Validate()
						if wantOK && res != OK {
							t.Fatalf("flags=0x%04x plen=%d ref=0x%x corr=0x%x should accept, got %s",
								f.HdrFlags, l, rr, cc, res)
						}
						if !wantOK && res == OK {
							t.Fatalf("flags=0x%04x plen=%d ref=0x%x corr=0x%x should refuse",
								f.HdrFlags, l, rr, cc)
						}
						if wantOK {
							accepted++
						} else {
							refused++
						}
					}
				}
			}
		}
	}
	t.Logf("validation axes: %d accepted, %d refused", accepted, refused)
}
